mapper.select:
SELECT count(*)
FROM member_role mr
JOIN clan_membership m ON m.id = mr.membership_id
JOIN app_role r ON r.id = mr.role_id
WHERE m.clan_id = #{clanId}
  AND m.member_status = #{memberStatus}
  AND mr.status = #{grantStatus}
  AND r.role_code = #{roleCode}
  AND mr.scope_type = #{scopeType}
